export async function refreshSession(token: string) {
  const session = await db.sessions.findByToken(token);
  if (!session || session.expiresAt < new Date()) return null;
  return createSessionCookie(session.userId);
}

export function Button({ label, onClick }: Props) {
  return <button type="button" onClick={onClick}>{label}</button>;
}

export async function createPayment(input: PaymentInput) {
  const response = await fetch(PAYMENTS_URL, { method: 'POST', body: JSON.stringify(input) });
  if (!response.ok) throw new PaymentError('provider rejected request');
  return response.json();
}

def build_profile(entries):
    usable = [entry for entry in entries if entry.get('value')]
    return sorted(usable, key=lambda entry: entry['created_at'], reverse=True)[:3]
